"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["95083"],{63589(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_vagas_obrigatoria","status":422,"titulo":"Composi\xe7\xe3o de vagas da modalidade \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_vagas_obrigatoria","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada n\xe3o declarou `composicaoVagas`. A composi\xe7\xe3o de\\nvagas decide como a modalidade entra na aritm\xe9tica do quadro de vagas \u2014\\nampla concorr\xeancia residual, sub-reserva da Lei 12.711, retirada de outra\\nmodalidade (`RETIRADA_DE_OUTRA_MODALIDADE`, ver\\n[`composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria)),\\nou suplemento ao total publicado. Roda antes das confer\xeancias de coer\xeancia de\\n`RETIRADA_DE_OUTRA_MODALIDADE` \u2014 sem uma composi\xe7\xe3o declarada, n\xe3o h\xe1 como avaliar se o c\xf3digo\\nde origem \xe9 coerente com ela.","**`composicaoVagas` n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de\\nvagas** \u2014 \xe9 copiada do cadastro de modalidades de Configura\xe7\xe3o, no momento\\nem que a modalidade \xe9 selecionada. O cadastro nunca grava uma modalidade sem esse campo \u2014 quando ele \xe9 omitido no cadastro, um\\nvalor padr\xe3o (`RESTANTE_DAS_VAGAS_OFERTADAS`) \xe9 aplicado; n\xe3o existe modalidade cadastrada\\ncom composi\xe7\xe3o de vagas literalmente vazia. O que dispara este c\xf3digo, na\\npr\xe1tica, \xe9 o valor de composi\xe7\xe3o do cadastro **n\xe3o ser reconhecido** pelo\\nvocabul\xe1rio do m\xf3dulo Sele\xe7\xe3o \u2014 hoje os dois vocabul\xe1rios coincidem, ent\xe3o\\no cen\xe1rio real \xe9 uma diverg\xeancia futura entre eles (o cadastro evoluindo\\nantes deste m\xf3dulo), n\xe3o um dado corrompido.","Sem composi\xe7\xe3o reconhecida, o c\xf3digo de origem n\xe3o \xe9 conferido. Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo."],"comoResolver":["O campo n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade cadastrada\\nem Configura\xe7\xe3o. Confira l\xe1 a composi\xe7\xe3o de vagas cadastrada; se ela\\nparecer correta e o erro persistir, \xe9 sinal de que o valor cadastrado n\xe3o \xe9 mais reconhecido pelo m\xf3dulo Sele\xe7\xe3o \u2014 um\\nproblema de sincroniza\xe7\xe3o entre os dois vocabul\xe1rios, n\xe3o de dado ausente."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);